final class Box {
    var tag: String
    init(tag: String) { self.tag = tag }
}

struct SafeBox {
    private var box: Box
    init(tag: String) { self.box = Box(tag: tag) }

    var tag: String {
        get { box.tag }
        set {
            if !isKnownUniquelyReferenced(&box) {
                box = Box(tag: box.tag)
            }
            box.tag = newValue
        }
    }
}

var boxA = SafeBox(tag: "Alpha")
var boxB = boxA
boxB.tag = "Beta"

print("\(boxA.tag) & \(boxB.tag)")

