final class DataStorage {
    var items: [Int]
    init(items: [Int]) { self.items = items }
}

struct SmartArray {
    private var storage: DataStorage
    init(items: [Int]) { self.storage = DataStorage(items: items) }
    var items: [Int] { storage.items }

    mutating func append(_ item: Int) {
        if !isKnownUniquelyReferenced(&storage) {
            storage = DataStorage(items: storage.items)
        }
        storage.items.append(item)
    }
}

var a = SmartArray(items: [1])
var b = a
b.append(2)
print("a: \(a.items.count), b: \(b.items.count)")
